window.createAnalyticsUI=function(ctx){
 const {state,esc,money,heading,panel,table,button,api,notify,can,today}=ctx;
 let filtersOpen=false;
 let filters={from:today().slice(0,7)+'-01',to:today(),group:'month'},tab='Overview',report='documents',page=1,result=null,charts=[],observers=[],generation=0,chartMode='bar',sort='desc';
 const $=s=>document.querySelector(s),keys=['from','to','product','category','itemType','warehouse','customer','supplier','documentType','documentStatus','purchaseStatus','expenseCategory','orderStatus','stockStatus','search','group'];
 const tabs=['Overview','Sales','Financial','Customers','Products','Operations','Reports','Pipeline'];
 const select=(key,label,values)=>'<label>'+esc(label)+'<select data-af="'+key+'"><option value="">All</option>'+values.map(v=>{const [id,name]=Array.isArray(v)?v:[v,v];return '<option value="'+esc(id)+'" '+(filters[key]===id?'selected':'')+'>'+esc(name)+'</option>';}).join('')+'</select></label>';
 const unique=(kind,key)=>[...new Set(state()[kind].map(x=>x[key]).filter(Boolean))].sort();
 function view(){const s=state();return heading('Business Analytics','Explore your sales, stock, customers and costs with connected business data.','<button id="analytics-filter-toggle" data-action="an-toggle-filters" aria-controls="analytics-filter-panel" aria-expanded="'+filtersOpen+'">'+(filtersOpen?'Hide filters':'Show filters')+'</button>'+button('Refresh data','an-refresh')+(can('export')?button('Export Excel','an-export','',true):''))+'<section id="analytics-filter-panel" class="panel analytics-controls" '+(filtersOpen?'':'hidden')+'><div class="toolbar">'+['Today','This week','This month','This quarter','This year','All time'].map(p=>button(p,'an-preset',p)).join('')+button('Reset filters','an-reset')+'</div><div class="analytics-filters"><label>From<input type="date" data-af="from" value="'+esc(filters.from||'')+'"></label><label>To<input type="date" data-af="to" value="'+esc(filters.to||'')+'"></label>'+select('product','Product / part',s.products.filter(p=>!p.archived).map(p=>[p.id,p.name]))+select('category','Inventory category',unique('products','category'))+select('itemType','Inventory type',['Product','Part'])+select('warehouse','Warehouse / branch',s.warehouses.map(w=>[w.id,w.name]))+select('customer','Customer · sales/orders',s.customers.map(c=>[c.id,c.name]))+select('supplier','Supplier · purchases',s.suppliers.map(c=>[c.id,c.name]))+select('documentType','Document type',['Quotation','Invoice','Proforma','Credit Note'])+select('documentStatus','Document status',['Draft','Sent','Accepted','Rejected','Converted','Issued','Cancelled'])+select('purchaseStatus','Purchase status',['Ordered','Partially received','Received'])+select('expenseCategory','Expense category',unique('expenses','category'))+select('orderStatus','Order status',['Confirmed','Packed','Dispatched','Delivered'])+select('stockStatus','Current stock',[['low','At/below reorder'],['out','Out of stock'],['available','Above reorder']])+select('group','Trend interval',[['day','Daily'],['week','Weekly'],['month','Monthly'],['quarter','Quarterly'],['year','Yearly']])+'<label>Search records<input data-af="search" value="'+esc(filters.search||'')+'" placeholder="Name, reference, description"></label></div><div class="toolbar">'+button('Apply filters','an-apply','',true)+'<span class="hint">Each filter applies to linked data. See Pipeline for scope and calculation rules.</span></div></section><div class="tabs analytics-tabs">'+tabs.map(t=>'<button data-action="an-tab" data-id="'+t+'" class="'+(tab===t?'active':'')+'">'+t+'</button>').join('')+'</div><div id="analytics-result" aria-live="polite"><div class="loading">Calculating your business data…</div></div>';}
 function destroy(){generation++;charts.forEach(c=>c.dispose());charts=[];observers.forEach(o=>o.disconnect());observers=[];}
 async function mount(){const ticket=++generation;try{const data=await api('analytics?'+new URLSearchParams(filters));if(ticket!==generation||!$('#analytics-result'))return;result=data;draw();}catch(e){if(ticket===generation&&$('#analytics-result'))$('#analytics-result').innerHTML='<div class="note">'+esc(e.message)+' '+button('Retry','an-refresh')+'</div>';}}
 function card(label,key,format='money',note=''){const v=result.kpis[key],old=result.previous?.[key],display=v==null?'Not available':format==='money'?money(v):format==='percent'?v.toFixed(1)+'%':v;let comparison='';if(old!=null){comparison=old===0?'Previous: '+(format==='money'?money(old):old)+' · percentage unavailable':((v-old)/Math.abs(old)*100).toFixed(1)+'% vs previous period';}return '<div class="card stat" title="'+esc(note)+'"><div class="stat-top">'+esc(label)+'</div><strong>'+esc(display)+'</strong><small>'+esc(comparison||note)+'</small></div>';}
 function chartBox(id,title,subtitle=''){return panel(title,'<div id="'+id+'" class="business-chart" role="img" aria-label="'+esc(title)+'"></div>','',subtitle);}
 function draw(){charts.forEach(c=>c.dispose());charts=[];observers.forEach(o=>o.disconnect());observers=[];const a=result;let body='';
 if(tab==='Pipeline'){body=panel('Saved records → tenant scope → filters → calculations → charts',table(['Source','Available records','Selected records'],Object.entries(a.pipeline.read).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+v+'</td><td>'+a.pipeline.selected[k]+'</td></tr>'))+'<p class="hint">Recomputed from saved database records on each refresh. Last calculation: '+esc(new Date(a.generatedAt).toLocaleString())+'. No external feeds or background ETL are connected.</p>')+panel('Calculation and filter policy',a.notes.map(n=>'<p class="hint">'+esc(n)+'</p>').join(''));}
 else if(tab==='Reports'){body=reportView();}
 else {
 body='<div class="cards">'+card('Net revenue','revenue','money','Issued invoices less credits, excluding tax')+card('Operating expenses','expenses','money','Recorded expenses, not product allocated')+card('Estimated operating profit','profit','money','Revenue − snapshot costs − recorded expenses')+card('Profit margin','margin','percent','Estimated operating profit / positive revenue')+'</div><div class="cards">'+card('Issued invoices','invoiceCount','number')+card('Invoiced customers','customers','number')+card('Average net invoice value','aov','money','Net revenue / issued invoice count')+card('Revenue growth','growth','percent','Compared with previous equal-length period')+'</div>';
 if(!a.salesLines.length)body+='<div class="note">No issued sales or credit lines match these filters. Other source panels may still have records.</div>';
 if(tab==='Overview'||tab==='Financial')body+='<div class="grid-two">'+chartBox('an-trend','Revenue, expenses & profit','Recorded periods only. Hover for values; toggle series in the legend.')+chartBox('an-breakdown','Revenue to estimated profit','Snapshot product costs and recorded expenses.')+'</div>';
 if(tab==='Sales'||tab==='Products'||tab==='Overview')body+='<div class="grid-two">'+chartBox('an-products','Product revenue','Click a bar to filter the dashboard; top 20 shown.')+chartBox('an-categories','Revenue by category','Negative credit balances use a bar chart; otherwise a donut.')+'</div>';
 if(tab==='Customers')body+='<div class="cards">'+card('Adjacent-period retention','retention','percent','Repeat invoiced customers / previous-period invoiced customers')+'</div>'+chartBox('an-customers','Customer net revenue','Top 20 customers; click to filter sales and orders.');
 if(tab==='Financial')body+='<div class="grid-two">'+chartBox('an-expenses','Expense distribution')+chartBox('an-suppliers','Purchase value by supplier','Before tax; purchase creation date.')+'</div>';
 if(tab==='Products')body+='<div class="cards">'+card('Current stock units','stockUnits','number','Current balance, independent of dates')+card('Current stock value','stockValue','money','Current units × current unit cost')+'</div>'+table(['Product / part','Category','Units','Current value'],a.products.slice(0,50).map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.category)+'</td><td>'+p.quantity+'</td><td>'+money(p.value)+'</td></tr>'));
 if(tab==='Operations')body+='<div class="cards">'+card('Sales orders','orders','number','Created within selected dates')+card('Purchase order value','purchaseValue','money','Selected purchase lines before tax')+'</div><div class="grid-two">'+chartBox('an-orders','Order fulfilment status','Status counts, not a conversion funnel.')+chartBox('an-documents','Quotation & billing status','Includes selected document types and statuses.')+'</div>'+chartBox('an-suppliers','Purchase value by supplier');
 body+=panel('Explore a visualization','<div class="toolbar"><label>Chart<select id="an-chart-mode">'+[['bar','Product revenue bars'],['line','Revenue trend'],['area','Cumulative net revenue'],['scatter','Units sold vs net revenue'],['histogram','Invoice value distribution'],['heatmap','Sales by month and category'],['pareto','Product revenue concentration']].map(([k,n])=>'<option value="'+k+'" '+(chartMode===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Rank order<select id="an-sort"><option value="desc" '+(sort==='desc'?'selected':'')+'>Highest first</option><option value="asc" '+(sort==='asc'?'selected':'')+'>Lowest first</option></select></label></div><div id="an-explore" class="business-chart" role="img" aria-label="Selected business visualization"></div>');
 body+=panel('Evidence & next actions',a.insights.map(i=>'<div class="activity"><div class="activity-main"><strong>'+esc(i.title)+'</strong><small>'+esc(i.text)+'</small></div></div>').join(''),'','Calculated insights from your records. Generative AI is not configured.');
 }
 $('#analytics-result').innerHTML=body;$('#an-chart-mode')?.addEventListener('change',e=>{chartMode=e.target.value;draw();});$('#an-sort')?.addEventListener('change',e=>{sort=e.target.value;draw();});$('#an-report')?.addEventListener('change',e=>{report=e.target.value;page=1;draw();});plot();}
 function reportView(){const rows=result[report]||[],headers=rows.length?Object.keys(rows[0]):[],slice=rows.slice((page-1)*20,page*20);return panel('Filtered record details','<div class="toolbar"><select id="an-report">'+['documents','products','purchases','expenses','orders'].map(k=>'<option '+(report===k?'selected':'')+'>'+k+'</option>').join('')+'</select><span>'+rows.length+' records · page '+page+'</span>'+button('Previous','an-prev')+button('Next','an-next')+'</div>'+(rows.length?table(headers, slice.map(r=>'<tr>'+headers.map(h=>'<td>'+esc(r[h])+'</td>').join('')+'</tr>')):'<p class="hint">No records match these filters.</p>'));}
 function make(id,option,click){const el=$('#'+id);if(!el||!window.echarts)return;const dark=document.body.classList.contains('dark'),c=echarts.init(el,null,{renderer:'svg'});charts.push(c);c.setOption({backgroundColor:'transparent',color:['#187efa','#16a085','#f0aa29','#e26464','#8664db'],textStyle:{color:dark?'#d9e7f8':'#455b76'},aria:{enabled:true},tooltip:{trigger:'item',renderMode:'richText'},grid:{left:65,right:25,top:45,bottom:70,containLabel:true},...option});if(click)c.on('click',click);if(typeof ResizeObserver!=='undefined'){const o=new ResizeObserver(()=>c.resize());o.observe(el);observers.push(o);}}
 const ordered=rows=>[...rows].sort((a,b)=>sort==='asc'?a.value-b.value:b.value-a.value).slice(0,20);
 function bars(id,rows,click,moneyValues=true){const v=ordered(rows);make(id,{xAxis:{type:'category',data:v.map(x=>x.name),axisLabel:{rotate:25,hideOverlap:true}},yAxis:{type:'value',name:moneyValues?'INR':'Count'},series:[{type:'bar',data:v.map(x=>moneyValues?x.value/100:x.value),barMaxWidth:45}]},click);}
 function pie(id,rows,click){if(rows.some(r=>r.value<0))return bars(id,rows,click);make(id,{legend:{type:'scroll',bottom:0},series:[{type:'pie',radius:['40%','65%'],label:{formatter:'{b}: {d}%'},data:rows.map(r=>({name:r.name,value:r.value/100}))}]},click);}
 function plot(){if(!result)return;const a=result,productClick=p=>{const product=state().products.find(x=>x.name===p.name);if(product){filters.product=product.id;ctx.render();}},customerClick=p=>{const customer=state().customers.find(x=>x.name===p.name);if(customer){filters.customer=customer.id;ctx.render();}};
 const trendOption={tooltip:{trigger:'axis',renderMode:'richText'},legend:{data:['Revenue','Expenses','Profit']},xAxis:{type:'category',data:a.trend.map(t=>t.name)},yAxis:{type:'value',name:'INR'},series:['revenue','expenses','profit'].map((k,i)=>({name:['Revenue','Expenses','Profit'][i],type:'line',showSymbol:true,data:a.trend.map(t=>t[k]/100)}))};
 make('an-trend',trendOption);bars('an-products',a.byProduct,productClick);pie('an-categories',a.byCategory,p=>{filters.category=p.name;ctx.render();});bars('an-customers',a.byCustomer,customerClick);pie('an-expenses',a.byExpense,p=>{filters.expenseCategory=p.name;ctx.render();});bars('an-suppliers',a.bySupplier);bars('an-orders',a.orderStatus,null,false);bars('an-documents',a.documentStatus,null,false);
 const r=a.kpis.revenue/100,c=a.kpis.cost/100,e=a.kpis.expenses/100,p=a.kpis.profit/100;
 // Floating bars use min endpoints, including negative profits.
 const starts=[0,r-c,p,0],ends=[r,r,r-c,p];make('an-breakdown',{xAxis:{type:'category',data:['Revenue','Product costs','Expenses','Profit']},yAxis:{type:'value',name:'INR'},series:[{type:'custom',renderItem:(params,api)=>{const x=api.value(0),start=api.coord([x,api.value(1)]),end=api.coord([x,api.value(2)]),width=api.size([1,0])[0]*.5;return {type:'rect',shape:{x:start[0]-width/2,y:Math.min(start[1],end[1]),width,height:Math.max(1,Math.abs(start[1]-end[1]))},style:{fill:['#187efa','#e26464','#e26464',p>=0?'#16a085':'#e26464'][x]}};},data:starts.map((v,i)=>[i,v,ends[i]])}]});
 if(chartMode==='bar')bars('an-explore',a.byProduct,productClick);
 if(chartMode==='line')make('an-explore',trendOption);
 if(chartMode==='area'){let total=0;make('an-explore',{xAxis:{type:'category',data:a.trend.map(t=>t.name)},yAxis:{type:'value',name:'Cumulative INR'},series:[{type:'line',areaStyle:{opacity:.2},data:a.trend.map(t=>(total+=t.revenue)/100)}]});}
 if(chartMode==='scatter'){const m=new Map();a.salesLines.forEach(l=>{const v=m.get(l.product)||{name:l.product,units:0,revenue:0};v.units+=l.units;v.revenue+=l.revenue;m.set(l.product,v);});make('an-explore',{xAxis:{type:'value',name:'Net units sold'},yAxis:{type:'value',name:'Net revenue INR'},series:[{type:'scatter',symbolSize:14,data:[...m.values()].map(v=>({name:v.name,value:[v.units,v.revenue/100]}))}]});}
 if(chartMode==='histogram'){const values=a.documents.filter(d=>d.type==='Invoice'&&d.status==='Issued').map(d=>d.subtotal/100),max=Math.max(...values,1),size=max/5,bins=Array.from({length:5},(_,i)=>({name:(i*size).toFixed(0)+'–'+((i+1)*size).toFixed(0),value:0}));values.forEach(v=>bins[Math.min(4,Math.floor(v/size))].value++);make('an-explore',{xAxis:{type:'category',data:bins.map(b=>b.name),name:'Invoice INR'},yAxis:{type:'value',name:'Invoices'},series:[{type:'bar',data:bins.map(b=>b.value)}]});}
 if(chartMode==='heatmap'){const months=[...new Set(a.salesLines.map(l=>l.date.slice(0,7)))].sort(),cats=[...new Set(a.salesLines.map(l=>l.category))].slice(0,20),m=new Map();a.salesLines.forEach(l=>{const k=months.indexOf(l.date.slice(0,7))+','+cats.indexOf(l.category);m.set(k,(m.get(k)||0)+l.revenue/100);});const points=[...m].filter(([k])=>!k.endsWith(',-1')).map(([k,v])=>[...k.split(',').map(Number),v]);make('an-explore',{xAxis:{type:'category',data:months},yAxis:{type:'category',data:cats},visualMap:{min:Math.min(0,...points.map(p=>p[2])),max:Math.max(1,...points.map(p=>p[2])),orient:'horizontal',bottom:0,left:'center',calculable:true},series:[{type:'heatmap',data:points}]});}
 if(chartMode==='pareto'){const rows=a.byProduct.filter(p=>p.value>0).sort((a,b)=>b.value-a.value),total=rows.reduce((s,r)=>s+r.value,0);let cumulative=0;make('an-explore',{legend:{data:['Positive revenue','Cumulative share']},xAxis:{type:'category',data:rows.map(r=>r.name),axisLabel:{hideOverlap:true}},yAxis:[{type:'value',name:'INR'},{type:'value',name:'%',min:0,max:100}],series:[{name:'Positive revenue',type:'bar',data:rows.map(r=>r.value/100)},{name:'Cumulative share',type:'line',yAxisIndex:1,data:rows.map(r=>total?(cumulative+=r.value)/total*100:0)}]});}
 }
 async function action(name,id){if(!name.startsWith('an-'))return false;if(name==='an-toggle-filters'){filtersOpen=!filtersOpen;const panel=$('#analytics-filter-panel'),toggle=$('#analytics-filter-toggle');if(panel)panel.hidden=!filtersOpen;if(toggle){toggle.setAttribute('aria-expanded',String(filtersOpen));toggle.textContent=filtersOpen?'Hide filters':'Show filters';}}else if(name==='an-apply'){document.querySelectorAll('[data-af]').forEach(el=>filters[el.dataset.af]=el.value);page=1;await mount();}else if(name==='an-refresh')await mount();else if(name==='an-reset'){filters={from:today().slice(0,7)+'-01',to:today(),group:'month'};page=1;ctx.render();}else if(name==='an-tab'){tab=id;page=1;ctx.render();}else if(name==='an-preset'){const now=today(),d=new Date(now+'T00:00:00Z');filters.to=now;if(id==='All time'){filters.from='';filters.to='';}else if(id==='Today')filters.from=now;else if(id==='This week'){d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);filters.from=d.toISOString().slice(0,10);}else if(id==='This month')filters.from=now.slice(0,7)+'-01';else if(id==='This quarter')filters.from=now.slice(0,4)+'-'+String(Math.floor((Number(now.slice(5,7))-1)/3)*3+1).padStart(2,'0')+'-01';else filters.from=now.slice(0,4)+'-01-01';ctx.render();}else if(name==='an-prev'){page=Math.max(1,page-1);draw();}else if(name==='an-next'){page=Math.min(Math.max(1,Math.ceil(result[report].length/20)),page+1);draw();}else if(name==='an-export'){const a=await api('analytics?'+new URLSearchParams({...filters,export:'1'}));const sheets=[{name:'Metrics',headers:['Metric','Value (money in INR)'],rows:Object.entries(a.kpis).map(([k,v])=>[k,['revenue','cost','expenses','profit','aov','stockValue','purchaseValue'].includes(k)&&v!=null?v/100:v])},{name:'Filters and policy',headers:['Setting','Value'],rows:[...Object.entries(a.filters),...a.notes.map((n,i)=>['Policy '+(i+1),n])]}];for(const key of ['documents','products','purchases','expenses','orders']){const rows=a[key],headers=rows.length?Object.keys(rows[0]):['No matching records'];sheets.push({name:key,headers:headers.map(h=>['subtotal','total','value','amount'].includes(h)?h+' INR':h),rows:rows.map(r=>headers.map(h=>['subtotal','total','value','amount'].includes(h)?r[h]/100:r[h]))});}ctx.download('grow-high-analytics.xlsx',await GrowExcel.buffer(sheets),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');notify('Filtered Excel report downloaded.');}return true;}
 return {view,mount,destroy,action};
};
